<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verify Membership</title><style>*{box-sizing:border-box}body{margin:0;background:#edf4f0;font-family:Arial,sans-serif;color:#142b21;min-height:100vh;display:grid;place-items:center;padding:24px}.box{width:min(470px,100%);background:#fff;border-radius:22px;padding:30px;box-shadow:0 22px 60px #14392924}.brand{color:#126b4c;font-size:12px;font-weight:900;letter-spacing:.13em}.verified{display:inline-block;margin:20px 0 18px;background:#e4f5eb;color:#117148;border-radius:30px;padding:9px 14px;font-weight:800}.photo{width:130px;height:130px;border-radius:20px;object-fit:cover;background:#e9efec;border:4px solid #fff;box-shadow:0 8px 25px #183c2c28}.avatar{display:grid;place-items:center;font-size:44px;color:#126b4c;font-weight:800}.box h1{margin:18px 0 5px}.box p{color:#62756c;margin:5px 0}.facts{margin-top:22px;border-top:1px solid #e5ebe8}.facts div{display:flex;justify-content:space-between;padding:13px 0;border-bottom:1px solid #e5ebe8}.facts span{color:#74847d}.facts b.status{text-transform:uppercase;color:#117148}</style></head><body><main class="box"><div class="brand">LDA SPORTS COMPLEX</div><span class="verified">✓ Secure membership record</span><div>@if($photo)<img class="photo" src="{{ $photo }}" alt="Member photograph">@else<div class="photo avatar">{{ strtoupper(substr($member->full_name,0,1)) }}</div>@endif</div><h1>{{ $member->full_name }}</h1><p>{{ $member->sportsComplex->name }}</p><div class="facts"><div><span>Membership number</span><b>{{ $member->membership_no ?: $member->customer_no }}</b></div><div><span>Status</span><b class="status">{{ $member->status }}</b></div><div><span>Verified at</span><b>{{ now()->format('d M Y, h:i A') }}</b></div></div></main></body></html>
